class Solution {
    largestNodeTree(root) {
        if(!root) return;
        let curr = root;

        while(curr.right !== null) {
            curr = curr.right;
        }

        return curr.data;
    }

    smallestNodeTree(root) {
        if(!root) return;

        let curr = root;

        while(curr.left !== null) {
            curr = curr.left;
        }

        return curr.data;
    }
    isBST(root) {

        if(!root) return true;

        let leftLargest = this.largestNodeTree(root.left);

        if(leftLargest && leftLargest >= root.data) return false;

        let rightSmallest = this.smallestNodeTree(root.right);

        if(rightSmallest && rightSmallest <= root.data) return false;

        return this.isBST(root.left) && this.isBST(root.right);
